import {categories,statuses,deadline,today,candidates,validateProduct,addMonths} from './dates.js';
import {all,write} from './db.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let products=[],editing=null,photo='',quick='',restoreItems=null,busy=false,photoBusy=false,installPrompt;
const form=$('#productForm'),el=n=>form.elements.namedItem(n);
for(const [selector,options] of [['#categoryFilter',categories],['select[name=category]',categories],['#statusFilter',statuses],['select[name=status]',statuses]])$(selector).insertAdjacentHTML('beforeend',options.map(x=>`<option>${x}</option>`).join(''));
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4000);}
function confirmAction(title,body){$('#confirmTitle').textContent=title;$('#confirmBody').textContent=body;$('#confirmDialog').showModal();return new Promise(resolve=>{let done=v=>{$('#confirmDialog').close();resolve(v)};$('#confirmYes').onclick=()=>done(true);$('#confirmCancel').onclick=()=>done(false);$('#confirmDialog').oncancel=e=>{e.preventDefault();done(false)}});}
async function refresh(){products=await all();render();}
function render(){const active=products.filter(p=>!['使用 완료','사용 완료','폐기'].includes(p.status));const counts={expired:0,soon:0,unknown:0};for(const p of active){const d=deadline(p);if(!d.date)counts.unknown++;else if(d.days<0)counts.expired++;else if(d.days<=30)counts.soon++;}$('#total').textContent=active.length;for(const k in counts)$('#'+k).textContent=counts[k];const q=$('#search').value.trim().toLocaleLowerCase();let list=products.filter(p=>{const d=deadline(p),isActive=active.includes(p);return (!q||[p.name,p.brand,p.memo].some(x=>x.toLocaleLowerCase().includes(q)))&&(!$('#categoryFilter').value||p.category===$('#categoryFilter').value)&&(!$('#statusFilter').value||p.status===$('#statusFilter').value)&&(!quick||(isActive&&(quick==='active'||quick==='unknown'&&!d.date||quick==='expired'&&d.days!==null&&d.days<0||quick==='soon'&&d.days!==null&&d.days>=0&&d.days<=30)));});list.sort((a,b)=>$('#sort').value==='new'?b.createdAt.localeCompare(a.createdAt):$('#sort').value==='name'?a.name.localeCompare(b.name,'ko'):(Number(!active.includes(a))-Number(!active.includes(b))||(deadline(a).date||'9999').localeCompare(deadline(b).date||'9999')||a.name.localeCompare(b.name,'ko')));$('#count').textContent=list.length+'개';$('#quickBar').hidden=!quick;$('#quickText').textContent=({active:'관리 중인 제품',expired:'기한 경과',soon:'30일 이내',unknown:'날짜 확인 필요'})[quick]||'';
$('#cards').innerHTML=list.length?list.map(p=>{const d=deadline(p),completed=['사용 완료','폐기'].includes(p.status),tag=!d.date?'unknown':d.days<0?'expired':d.days<=30?'soon':'';return `<article class="card"><div class="card-image">${p.photo?`<img src="${p.photo}" alt="${esc(p.name)} 사진" loading="lazy">`:'<span class="placeholder" aria-hidden="true"></span>'}<span class="status-pill">${esc(p.status)}</span></div><div class="card-content"><div class="brand">${esc(p.brand||'나의 뷰티 기록')}</div><h3>${esc(p.name)}</h3><div class="due-line"><span class="badge ${completed?'':tag}">${completed?'관리 종료':d.label}</span><strong>${d.date?esc(d.date)+(completed?'':` · ${d.days<0?'+'+Math.abs(d.days):'D−'+d.days}`):'—'}</strong></div><p class="reason">${esc(d.reason)}</p><div class="card-bottom"><span>${esc(p.category)} · ${p.months?esc(p.months)+'M':'기간 미입력'}</span><button data-edit="${esc(p.id)}" aria-label="${esc(p.name)} 수정">기록 보기 ↗</button></div></div></article>`}).join(''):`<div class="empty"><div class="sprout">❀</div><h3>${products.length?'조건에 맞는 제품이 없어요':'아직 비어 있는 나의 화장대'}</h3><p>${products.length?'검색어나 필터를 바꿔 보세요.':'첫 번째 화장품을 기록해 보세요.<br>제품을 등록하면 먼저 써야 할 순서로 정리해 드려요.'}</p><button class="secondary" id="emptyAdd">＋ 제품 등록하기</button></div>`;$('#emptyAdd')?.addEventListener('click',()=>openEditor());}
function draft(){return {name:el('name').value.trim(),brand:el('brand').value.trim(),category:el('category').value,status:el('status').value,expiry:el('expiry').value,opened:el('opened').value,months:el('months').value?+el('months').value:null,memo:el('memo').value,photo};}
function calculation(){const d=deadline(draft());$('#calculation').textContent=`관리 기준일: ${d.date||'날짜 확인 필요'} · ${d.reason}`;}
function setPhoto(v){photo=v;$('#photoPreview').hidden=!v;$('#photoPreview').src=v||'';}
function openEditor(id){if(busy||photoBusy)return;editing=products.find(p=>p.id===id)||null;form.reset();$('#ocrPanel').hidden=true;$('#ocrText').value='';$('#dateCandidates').innerHTML='';$('#formError').textContent='';$('#editorTitle').textContent=editing?'제품 기록 수정':'제품 등록';$('#delete').hidden=!editing;for(const n of ['name','brand','category','status','expiry','opened','months','memo'])if(editing)el(n).value=editing[n]??'';setPhoto(editing?.photo||'');calculation();$('#editor').showModal();}
function controls(){ $('#save').disabled=busy||photoBusy;$('#ocr').disabled=busy||photoBusy;$('#photo').disabled=busy||photoBusy;$('#removePhoto').disabled=busy||photoBusy;$('#delete').disabled=busy||photoBusy;}
$('#add').onclick=()=>openEditor();$('#cards').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openEditor(b.dataset.edit)};for(const s of ['#search','#categoryFilter','#statusFilter','#sort'])$(s).addEventListener('input',render);document.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{quick=b.dataset.quick;render()});$('#clearQuick').onclick=()=>{quick='';render()};form.addEventListener('input',calculation);
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{if(busy||photoBusy)return;$('#'+b.dataset.close).close()});$('#editor').addEventListener('cancel',e=>{if(busy||photoBusy)e.preventDefault()});
form.onsubmit=async e=>{e.preventDefault();if(busy||photoBusy)return;$('#formError').textContent='';try{const p=validateProduct({...draft(),id:editing?.id||crypto.randomUUID(),createdAt:editing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()});if(p.opened>today())throw Error('개봉일이 오늘보다 미래입니다. 날짜를 확인해 주세요.');if(p.status==='미개봉'&&p.opened)throw Error('개봉일이 입력되어 있습니다. 상태를 사용 중으로 바꾸거나 개봉일을 지워 주세요.');busy=true;controls();await write([p]);await refresh();$('#editor').close();toast('제품 기록을 저장했어요.');}catch(e){$('#formError').textContent='저장하지 못했어요. '+e.message;}finally{busy=false;controls()}};
$('#delete').onclick=async()=>{if(!editing||busy)return;if(await confirmAction('제품을 삭제할까요?',`‘${editing.name}’의 사진과 기록이 이 브라우저에서 삭제됩니다.`)){try{await write([],editing.id);await refresh();$('#editor').close();toast('제품을 삭제했어요.')}catch(e){$('#formError').textContent=e.message}}};
$('#photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;photoBusy=true;controls();try{if(f.size>20000000)throw Error('20MB 이하의 사진을 선택해 주세요.');const url=URL.createObjectURL(f);try{const img=new Image();img.src=url;await img.decode();const scale=Math.min(1,2200/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);setPhoto(c.toDataURL('image/jpeg',.88));}finally{URL.revokeObjectURL(url)}}catch(e){$('#formError').textContent='사진을 읽지 못했어요. JPG·PNG·WebP로 다시 선택하거나 수동 입력해 주세요. '+e.message;}finally{photoBusy=false;controls()}};
$('#removePhoto').onclick=()=>{setPhoto('');$('#photo').value=''};
let enginePromise;
function loadEngine(){return enginePromise??=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>{enginePromise=null;s.remove();reject(Error('OCR 엔진 다운로드 실패. 인터넷 연결을 확인해 주세요.'))};document.head.append(s)});}
function showCandidates(){const cs=candidates($('#ocrText').value);$('#dateCandidates').innerHTML=cs.length?cs.map((c,i)=>`<button type="button" data-date-index="${i}" ${c.manufacture?'disabled class="manufacture"':''}>${esc(c.date)} · ${c.manufacture?'제조일 문맥 · 적용 불가':c.explicit?'사용기한 문맥 후보 · 확인 후 적용':'종류 불명 · 라벨에서 EXP인지 확인 후 적용'}<br>${esc(c.context)}</button>`).join(''):'<p class="hint">날짜 후보를 찾지 못했어요. 원문과 사진을 확인하고 직접 입력해 주세요.</p>';$('#dateCandidates').onclick=async e=>{const b=e.target.closest('[data-date-index]');if(!b)return;const c=cs[+b.dataset.dateIndex];if(c.manufacture)return;if(await confirmAction('사용기한이 맞나요?',`${c.date} · 사진에서 제조일이 아닌 EXP·사용기한인지 직접 확인한 후 적용하세요.`)){el('expiry').value=c.date;calculation();toast('사용기한 후보를 입력했어요. 저장 전 확인해 주세요.')}};}
$('#parseOcr').onclick=showCandidates;$('#applyName').onclick=()=>{if($('#ocrName').value.trim()){el('name').value=$('#ocrName').value.trim();toast('제품명을 입력했어요.')}};
$('#ocr').onclick=async()=>{if(!photo){toast('제품 사진을 먼저 선택해 주세요.');return}busy=true;controls();$('#ocrPanel').hidden=false;$('#ocrProgress').value=0;$('#ocrText').value='';$('#dateCandidates').innerHTML='';$('#ocrName').value='';$('#ocrStatus').textContent='최초 사용 시 엔진·언어 모델을 다운로드합니다. 잠시 기다려 주세요…';let worker;try{await loadEngine();worker=await Tesseract.createWorker('kor+eng',1,{logger:m=>{$('#ocrProgress').value=Math.round((m.progress||0)*100);const labels={'loading tesseract core':'OCR 엔진 다운로드','initializing tesseract':'엔진 준비','loading language traineddata':'한국어·영어 모델 다운로드','initializing api':'언어 모델 준비','recognizing text':'사진의 글자 인식'};$('#ocrStatus').textContent=(labels[m.status]||'OCR 준비 중')+(m.progress===undefined?'':` · ${Math.round(m.progress*100)}%`);}});const {data}=await worker.recognize(photo);$('#ocrText').value=data.text;$('#ocrName').value=(data.text.split('\n').map(x=>x.trim()).find(x=>x.length>2&&!/\d|EXP|MFG|제조|사용기한/i.test(x))||'').slice(0,120);showCandidates();$('#ocrStatus').textContent=data.text.trim()?'인식 완료 · 원문과 사진을 비교한 후 적용해 주세요.':'글자를 찾지 못했어요. 밝은 곳에서 라벨을 가까이 찍거나 수동으로 입력해 주세요.';}catch(e){$('#ocrStatus').textContent='OCR을 완료하지 못했어요. 인터넷 연결과 사진 형식을 확인하고 다시 시도하거나 수동 입력해 주세요. '+e.message;}finally{if(worker)await worker.terminate().catch(()=>{});busy=false;controls()}};
$('#sample').onclick=async()=>{if(!await confirmAction('샘플을 추가할까요?','가상 제품 4개가 개별 용기로 등록됩니다. 실제 제품이 아니며 기록 보기에서 삭제할 수 있어요.'))return;try{const base={brand:'뷰티기한 샘플',category:'스킨케어',status:'사용 중',opened:'',months:null,memo:'사용법을 살펴보기 위한 가상 샘플',photo:''},shift=n=>{const d=new Date(today()+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};await write([['[샘플] 수분 크림',shift(14)],['[샘플] 선크림',shift(-5)],['[샘플] 립 틴트',''],['[샘플] 클렌징 밀크',shift(100)]].map(([name,expiry],i)=>({...base,name,expiry,category:categories[i],id:crypto.randomUUID(),createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()})));await refresh();toast('가상 샘플 4개를 추가했어요.')}catch(e){toast('샘플 저장 실패: '+e.message)}};
for(const s of ['#backupOpen','#backupInline'])$(s).onclick=()=>$('#backupDialog').showModal();
$('#export').onclick=async()=>{try{const data={app:'beauty-deadline',version:1,exportedAt:new Date().toISOString(),products:await all()},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`뷰티기한-백업-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);$('#backupStatus').textContent='백업 다운로드를 요청했어요. 다운로드 폴더를 확인하세요.';}catch(e){$('#backupStatus').textContent='백업 실패: '+e.message}};
$('#importFile').onchange=async e=>{restoreItems=null;$('#restorePreview').hidden=true;try{const file=e.target.files[0];if(!file)return;if(file.size>100000000)throw Error('100MB 이하의 백업만 지원합니다.');const data=JSON.parse(await file.text());if(data.app!=='beauty-deadline'||data.version!==1||!Array.isArray(data.products)||data.products.length>2000)throw Error('뷰티기한 버전 1 백업인지 확인해 주세요.');const ids=new Set();restoreItems=data.products.map(p=>{validateProduct(p);if(ids.has(p.id))throw Error('중복 ID가 있는 백업입니다.');ids.add(p.id);if(typeof p.createdAt!=='string'||typeof p.updatedAt!=='string'||isNaN(Date.parse(p.createdAt))||isNaN(Date.parse(p.updatedAt)))throw Error('등록 시각이 올바르지 않습니다.');return Object.fromEntries(['id','name','brand','category','status','expiry','opened','months','memo','photo','createdAt','updatedAt'].map(k=>[k,p[k]??(k==='months'?null:'')]))});const overlap=restoreItems.filter(p=>products.some(q=>q.id===p.id)).length;$('#restoreInfo').textContent=`총 ${restoreItems.length}개 · 새로 추가 ${restoreItems.length-overlap}개 · 같은 ID 덮어쓰기 ${overlap}개`;$('#restorePreview').hidden=false;$('#backupStatus').textContent='내용을 확인한 후 복원 버튼을 눌러 주세요.';}catch(e){restoreItems=null;$('#backupStatus').textContent='복원 파일을 읽지 못했어요. '+e.message}};
$('#restore').onclick=async()=>{if(!restoreItems)return;$('#restore').disabled=true;try{await write(restoreItems);await refresh();$('#backupStatus').textContent=`${restoreItems.length}개 제품을 복원했어요.`;restoreItems=null;$('#restorePreview').hidden=true;$('#importFile').value='';toast('백업 복원을 완료했어요.')}catch(e){$('#backupStatus').textContent='복원 실패. 기존 기록은 유지됩니다. '+e.message}finally{$('#restore').disabled=false}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh().catch(e=>toast(e.message))});setInterval(()=>{if(!document.hidden)render()},60000);
try{await refresh()}catch(e){$('#cards').innerHTML='<div class="empty"><h3>저장 공간을 열 수 없어요</h3><p>브라우저의 저장 공간 권한과 비공개 모드를 확인하고 다시 열어 주세요.</p></div>';toast('저장소 오류: '+e.message)}
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('오프라인 준비에 실패했어요. 온라인에서는 계속 사용할 수 있습니다.'));
